export type RenownTier = "hero" | "strong" | "quiet";

export function renownOf(slug: string): RenownTier {
  if (HERO_SLUGS.has(slug)) return "hero";
  if (STRONG_SLUGS.has(slug)) return "strong";
  return "quiet";
}

export function renownScore(slug: string): number {
  const tier = renownOf(slug);
  return tier === "hero" ? 26 : tier === "strong" ? 13 : 0;
}
